{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError('case must be a dictionary')
    if set(case) - {'nodes', 'required_symbols', '_case_nonce'}:
        raise ValueError('unexpected case field')
    if 'nodes' not in case or 'required_symbols' not in case:
        raise ValueError('missing required field')
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    if not isinstance(nodes, list) or not nodes:
        raise ValueError('nodes must be a nonempty list')
    if not isinstance(required_symbols, list):
        raise ValueError('required_symbols must be a list')
    if any(not isinstance(symbol, str) for symbol in required_symbols):
        raise ValueError('required symbols must be strings')
    if len(set(required_symbols)) != len(required_symbols):
        raise ValueError('required symbols must be unique')

    by_id = {}
    source_index = {}
    for index, node in enumerate(nodes):
        if not isinstance(node, dict):
            raise ValueError('each node must be a dictionary')
        if set(node) != {'id', 'parent', 'symbol', 'depth', 'removable', 'utility'}:
            raise ValueError('invalid node fields')
        node_id = node['id']
        parent = node['parent']
        symbol = node['symbol']
        depth = node['depth']
        utility = node['utility']
        if not isinstance(node_id, str) or not node_id or node_id in by_id:
            raise ValueError('node ids must be unique nonempty strings')
        if parent is not None and (not isinstance(parent, str) or not parent):
            raise ValueError('invalid parent')
        if not isinstance(symbol, str):
            raise ValueError('invalid symbol')
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError('invalid depth')
        if not isinstance(node['removable'], bool):
            raise ValueError('invalid removable flag')
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise ValueError('invalid utility')
        by_id[node_id] = node
        source_index[node_id] = index

    roots = [node for node in nodes if node['parent'] is None]
    if len(roots) != 1:
        raise ValueError('tree must have exactly one root')
    root_id = roots[0]['id']
    if roots[0]['depth'] != 0:
        raise ValueError('root depth must be zero')
    for node in nodes:
        parent = node['parent']
        if parent is not None:
            if parent not in by_id or parent == node['id']:
                raise ValueError('invalid parent reference')
            if node['depth'] != by_id[parent]['depth'] + 1:
                raise ValueError('inconsistent depth')

    for node_id in by_id:
        seen = set()
        current = node_id
        while by_id[current]['parent'] is not None:
            if current in seen:
                raise ValueError('cycle in tree')
            seen.add(current)
            current = by_id[current]['parent']
        if current != root_id:
            raise ValueError('disconnected tree')

    initial_symbols = {node['symbol'] for node in nodes}
    if not set(required_symbols).issubset(initial_symbols):
        raise ValueError('required symbol is absent')

    ordered_candidates = sorted(
        nodes,
        key=lambda node: (-node['depth'], node['id'])
    )
    retained = set(by_id)
    removal_order = []
    for node in ordered_candidates:
        node_id = node['id']
        if not node['removable'] or node_id == root_id or node['symbol'] in required_symbols:
            continue
        if any(other['parent'] == node_id and other['id'] in retained for other in nodes):
            continue
        remaining_symbols = {
            by_id[other_id]['symbol']
            for other_id in retained
            if other_id != node_id
        }
        if not set(required_symbols).issubset(remaining_symbols):
            continue
        retained.remove(node_id)
        removal_order.append(node_id)

    retained_ids = sorted(retained)
    retained_utility = sum(by_id[node_id]['utility'] for node_id in retained_ids)
    removed_utility = sum(by_id[node_id]['utility'] for node_id in removal_order)
    return {
        'retained_ids': retained_ids,
        'removal_order': removal_order,
        'grammar_valid': True,
        'interestingness_preserved': True,
        'registered_candidate_order': [node['id'] for node in ordered_candidates],
        'stable_ties': True,
        'retained_utility': retained_utility,
        'removed_utility': removed_utility,
    }
